@import "pretendard/dist/web/variable/pretendardvariable.css";

/* PRISM light profile. Values are measured from PRISM-DEV and source design tokens. */
[data-prism="light"] {
    --prism-base: #fdfdfd; --prism-lnb: #f9fafc; --prism-panel: #eef1f8;
    --prism-border: #e3e5e5; --prism-control-border: #d4d8dd; --prism-divider: #e7e9ed;
    --prism-primary: #2f548c; --prism-secondary: #fa7c39;
    --prism-cool-100: #eef2fa; --prism-cool-200: #d6dcee; --prism-cool-700: #384a7d; --prism-cool-800: #1f3365;
    --prism-neutral-50: #f4f5f8; --prism-neutral-100: #e7eaee; --prism-neutral-200: #d7dce3; --prism-neutral-400: #8a939f;
    --prism-caption: #9aa3af; --prism-sub: #868686;
    --prism-blue-300: #2e8ed9; --prism-blue-400: #0072c6; --prism-cool-300: #b8c2da;
    --background: var(--prism-base); --surface: var(--prism-base); --foreground: #222;
    --surface-subtle: var(--prism-neutral-50); --border: var(--prism-control-border);
    --accent: var(--prism-primary); --accent-foreground: #fff; --muted: #626a75;
    --focus: #2e8ed9; --danger: #ea002c; --success: #256645; --warning: #95620a;
    --message-user-background: var(--prism-cool-100); --message-user-foreground: #222;
    --radius: 6px; --control-height: 32px; --density-control-height: 32px;
    --font-ui: "Pretendard Variable", Pretendard, sans-serif; --overlay: rgb(0 0 0 / 40%);
    --shadow-float: 0 4px 24px rgb(37 38 46 / 16%);
    --shadow-medium: 0 4px 16px rgb(37 38 46 / 12%);
    font-family: var(--font-ui); color: var(--foreground); background: var(--background);
    color-scheme: light;
}
[data-prism] *, [data-prism] *::before, [data-prism] *::after { box-sizing: border-box; }
[data-prism] button, [data-prism] input, [data-prism] textarea, [data-prism] select { font-family: inherit; }
[data-prism] :focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }
[data-prism] [hidden] { display: none !important; }
.prism-sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.prism-button { font-weight: 600; line-height: 1.4; flex-shrink: 0; gap: 4px; border-radius: 4px; opacity: 1; }
.prism-button[data-size="large"] { height: 40px; padding: 0 12px; border-radius: 6px; font-size: 16px; }
.prism-button[data-size="medium"] { height: 32px; padding: 0 12px; font-size: 14px; }
.prism-button[data-size="small"] { height: 28px; padding: 0 12px; font-size: 12px; }
.prism-button[data-size="x-small"] { height: 26px; padding: 0 8px; font-size: 12px; }
.prism-button[data-variant="solid"] { position: relative; border: 0; background: var(--accent); color: #fff; }
.prism-button[data-variant="solid"]::before { position:absolute;content:"";inset:0;pointer-events:none;border-radius:inherit;background:#ffffff29;opacity:0;transition:opacity .15s; }
.prism-button[data-variant="solid"][data-tone="danger"] { background: var(--danger); }
.prism-button[data-variant="line"] { border: 1px solid var(--prism-control-border); background: var(--surface); color: var(--foreground); }
.prism-button[data-variant="line"][data-tone="primary"]:not(:disabled) { border-color:var(--prism-primary);color:var(--prism-primary); }
.prism-button[data-variant="shape"] { border: 0; background: transparent; color: var(--foreground); }
.prism-button[data-variant="solid"]:hover:not(:disabled)::before { opacity:1; }
.prism-button[data-variant="solid"][data-tone="danger"]:hover:not(:disabled) { background: #e45858; }
.prism-button[data-variant="line"]:hover:not(:disabled) { background: var(--surface-subtle); }
.prism-button[data-variant="shape"]:hover:not(:disabled) { background: var(--prism-cool-100); }
.prism-button:disabled { pointer-events: auto; cursor: not-allowed; opacity: 1; color: var(--prism-caption); }
.prism-button[data-variant="solid"]:disabled { background: var(--prism-neutral-200); }
.prism-button[data-variant="line"]:disabled { color: rgb(34 34 34 / 30%); }
.prism-button[data-variant="shape"]:disabled { color:var(--prism-cool-300); }
.prism-button[data-icon-only] { width:32px;padding:0; }
.prism-button[data-size="large"][data-icon-only] { width:40px; }
.prism-button[data-size="small"][data-icon-only] { width:28px;border-radius:6px; }
.prism-button[data-size="x-small"][data-icon-only] { width:26px; }
.prism-button[data-size="medium"]:not([data-icon-only]):has(.prism-button-icon) {padding-left:8px;}
.prism-button[data-size="small"]:not([data-icon-only]):has(.prism-button-icon) {padding:0 8px 0 6px;}
.prism-button[data-size="x-small"]:not([data-icon-only]):has(.prism-button-icon) {padding:0 4px 0 8px;}
.prism-button-icon { display: inline-flex; align-items: center; justify-content: center; }
.prism-button-icon svg { width: 20px; height: 20px; }
.prism-button[data-size="large"] .prism-button-icon svg { width: 16px; height: 16px; }
.prism-button[data-size="x-small"] .prism-button-icon svg { width:14px;height:14px; }
.prism-new-chat[data-variant="solid"] { width: 100%; border: 1px solid #416395; border-radius: 8px; background: linear-gradient(90deg,#44689f,#284d85); font-size: 14px; }
.prism-new-chat .prism-button-icon svg { width: 28px; height: 28px; }
.prism-new-chat[data-variant="solid"]:hover:not(:disabled) { border:0;background:var(--prism-primary); }
.prism-field { display: grid; gap: 6px; min-width: 0; }
.prism-field > label { font-size: 14px; font-weight: 600; line-height: 1.4; }
.prism-required, .prism-error { color: var(--danger); }
.prism-input { height: 32px; padding: 6px 12px; border-radius: 6px; font-size: 14px; font-weight: 500; line-height: 1.4; border-color: var(--prism-control-border); opacity: 1; }
.prism-input[data-size="small"] { height: 28px; padding: 4px 12px; }
.prism-input::placeholder, .prism-textarea::placeholder { color: var(--prism-caption); opacity: 1; }
.prism-input:focus, .prism-textarea:focus { border-color: var(--focus); }
.prism-input:disabled, .prism-textarea:disabled { background: var(--prism-neutral-50); color: var(--prism-caption); opacity: 1; }
.prism-input:read-only,.prism-textarea:read-only {background:var(--prism-neutral-50);}
.prism-input:hover:not(:disabled):not(:read-only) {border-color:var(--prism-blue-300);}
.prism-input[aria-invalid="true"], .prism-textarea[aria-invalid="true"] { border-color: var(--danger); }
.prism-input[aria-invalid="true"]:focus:not(:read-only), .prism-textarea[aria-invalid="true"]:focus:not(:read-only) {border-color:var(--danger);}
.prism-help, .prism-error { font-size: 12px; line-height: 17px; margin: 0; }
.prism-help { color: var(--muted); }
.prism-textarea { font-size: 14px; font-weight: 500; padding: 6px 12px; border-radius: 6px; }
.prism-input-control {display:flex;align-items:center;border:1px solid var(--prism-control-border);border-radius:6px;background:var(--prism-base);overflow:hidden;}
.prism-input-control>.prism-input {border:0;background:transparent;height:30px;outline:none;}
.prism-input-control[data-size="small"]>.prism-input {height:26px;}
.prism-input-control[data-size="large"]>.prism-input {height:38px;}
.prism-input-control:hover:not([data-disabled]):not([data-readonly]),.prism-input-control:focus-within:not([data-readonly]) {border-color:var(--prism-blue-300);}
.prism-input-control[data-disabled],.prism-input-control[data-readonly] {background:var(--prism-neutral-50);}
.prism-input-control[data-invalid] {border-color:var(--danger);}
.prism-input-adornment {display:flex;align-items:center;gap:6px;margin-right:12px;}
.prism-input-adornment>button {display:grid;place-items:center;width:20px;height:20px;padding:0;border:0;background:none;cursor:pointer;color:#8a939f;}
.prism-elp { display: inline-flex; align-items: center; justify-content: center; height: 16px; padding: 2px 4px; border-radius: 10px; font-size: 10px; line-height: 1; font-weight: 600; white-space: nowrap; }
.prism-elp[data-type="s-ELP"] { border: 1px solid #d2daaa; background: #f6fcd6; color: #6a7b00; }
.prism-elp[data-type="ELP"] { border: 1px solid #e5d9f2; background: #f4ecfa; color: #68127a; }
.prism-count { display: inline-flex; align-items: center; justify-content: center; min-width: 14px; height: 14px; padding: 0 4px; border-radius: 10px; background: var(--prism-secondary); color: #fff; font-size: 10px; font-weight: 500; }
.prism-tag { display: inline-flex; align-items: center; justify-content: center; height: 21px; padding: 2px 4px; border-radius: 4px; font-size: 12px; line-height: 1.4; font-weight: 500; gap: 2px; border: 1px solid var(--prism-border); background: var(--prism-neutral-50); }
.prism-tag[data-variant="blue"] { font-weight: 600; border-color: var(--prism-cool-200); background: var(--prism-cool-100); color: var(--accent); }
.prism-tag[data-variant="mainBlue"] { font-weight: 600; border:0; background: var(--prism-cool-800); color: #fff; }
.prism-tag button { border: 0; background: none; padding: 0; display: inline-flex; color: inherit; }
.prism-chip { display: inline-flex; align-items: center; justify-content: center; height: 22px; padding: 2px 8px; border-radius: 4px; font-size: 12px; font-weight: 600; line-height: 1.4; background: color-mix(in srgb,var(--chip-tone) 10%,transparent); color: var(--chip-tone); }
.prism-chip[data-variant="solid"] { background: var(--chip-tone); color: #fff; font-size: 14px; }
.prism-avatar { display: flex; align-items: center; gap: 12px; min-width: 0; width:100%; }
.prism-avatar-image { width: 40px; height: 40px; border: 0; border-radius: 25px; background: #626a75; color: #fff; }
.prism-avatar-image > span { font-size: 20px; font-weight: 600; }
.prism-avatar-text { min-width: 0; max-width: calc(100% - 52px); overflow: hidden; }
.prism-avatar-text > div { display: flex; align-items: center; gap: 6px; width:100%; }
.prism-avatar-text [data-info-layout="name-truncate"] .prism-avatar-team,.prism-avatar-text [data-info-layout="team-truncate"] .prism-avatar-name { flex-shrink: 0; }
.prism-avatar-text [data-info-layout="both-truncate"] .prism-avatar-name,.prism-avatar-text [data-info-layout="both-truncate"] .prism-avatar-team { max-width: calc((100% - 13px) / 2); }
.prism-avatar-text .prism-avatar-name:focus-visible,.prism-avatar-text .prism-avatar-team:focus-visible { outline: 2px solid var(--prism-primary); outline-offset: -2px; border-radius: 2px; }
.prism-avatar-text strong { font-size: 14px; font-weight: 600; line-height:1.4; }
.prism-avatar-text strong,.prism-avatar-text span:not(.prism-avatar-divider),.prism-avatar-text p {min-width:0;overflow:hidden;white-space:nowrap;text-overflow:ellipsis;}
.prism-avatar-divider {flex-shrink:0;}
.prism-avatar-text span, .prism-avatar-text p { font-size: 12px; line-height: 1.4; }
.prism-avatar-text p { margin: 0; color: var(--prism-sub); font-weight:500; }
.prism-avatar-divider { width: 1px; height: 12px; background: var(--prism-control-border); }
.prism-profile-chip { display: inline-flex; align-items: center; gap: 10px; height: 30px; padding: 0 16px 0 0; border: 1px solid var(--prism-neutral-100); border-radius: 20px; background: #fff; font-size: 14px; font-weight: 500; }
.prism-profile-chip-image { width: 30px; height: 30px; margin-left: -1px; }
.prism-profile-chip {overflow:hidden;flex-shrink:0;cursor:pointer;}
.prism-profile-chip-image {border:1px solid var(--prism-neutral-100);background:#fff;}
.prism-profile-chip:hover:not(:disabled),.prism-profile-chip:hover:not(:disabled) .prism-profile-chip-image {border-color:#416395;}
.prism-profile-chip[data-readonly] {background:var(--prism-neutral-100);cursor:default;}
.prism-profile-chip[data-small] { height: 27px; font-size: 12px; gap: 8px; padding-right: 14px; }
.prism-profile-chip[data-small] .prism-profile-chip-image { width: 27px; height: 27px; }
.prism-anchor-chip { display:inline-flex;align-items:center;justify-content:center;min-height: 30px; padding: 0 12px; border: 1px solid var(--prism-neutral-100); border-radius: 999px; background: #fff; font-size: 14px; font-weight: 500; }
.prism-anchor-chip[aria-pressed="true"],.prism-anchor-chip[data-selected] { border-color: var(--accent); background: var(--accent); color: #fff; }
.prism-anchor-chip[data-static] {cursor:default;}
.prism-anchor-chip[data-small] {min-height:25px;height:25px;font-size:12px;}
.prism-tabs-root,.prism-tabs-content {min-width:0;max-width:100%;}
.prism-tabs { display: flex; gap: 24px; min-height: 44px; border-bottom: 1px solid #e9eaea;max-width:100%;min-width:0;overflow-x:auto; }
.prism-tab { height: 44px; padding: 0 10px; font-size: 13px; font-weight: 500; color: var(--prism-sub); border-radius: 0; }
.prism-tab[data-state="active"] { font-weight: 600; color: var(--accent); background: transparent; border-bottom-color: var(--accent); }
.prism-tabs[data-prism-variant="fill"] { gap: 4px; min-height: 46px; padding: 14px 2px 0; background: var(--prism-neutral-50); border: 0; border-radius: 0; }
.prism-tabs[data-prism-variant="fill"] .prism-tab { height: 32px; padding: 6px 16px; border-radius: 6px 6px 0 0; font-size: 14px; }
.prism-tabs[data-prism-variant="fill"] .prism-tab[data-state="active"] { background: var(--surface); box-shadow: 0 0 4px #0000000a; }
.prism-table-scroll { overflow: auto; width: 100%;max-width:100%;min-width:0; max-height: 500px; border-bottom: 1px solid var(--prism-neutral-200); }
.prism-table { border-collapse: separate; border-spacing: 0; width: 100%; font-size: 14px; text-align: left; }
.prism-table caption { text-align: left; padding: 0 0 12px; font-size: 18px; font-weight: 600; }
.prism-table th, .prism-table td { padding: 10px; border-bottom: 1px solid var(--prism-neutral-200); border-right: 1px solid var(--prism-neutral-200); line-height: 1.4; vertical-align: top; white-space: pre-line; }
.prism-table thead th { padding: 6px 10px; background: var(--prism-cool-100); font-weight: 600; position: sticky; top: 0; }
.prism-table tr > :last-child { border-right: 0; }
.prism-table tr:last-child td { border-bottom: 0; }
.prism-data-table th { padding: 6px 10px; background: var(--prism-cool-100); font-weight: 600; }
.prism-data-table td { padding: 10px; border-color: var(--prism-neutral-200); }
.prism-section > header { display: flex; justify-content: space-between; align-items: center; gap: 12px; margin-bottom: 8px; }
.prism-section h3 { margin: 0; font-size: 14px; font-weight: 600; line-height: 1.4; }
.prism-dialog { display:flex;flex-direction:column;padding:0;border:0;border-radius:8px;width:var(--prism-dialog-width,620px);max-width:calc(100vw - 64px);max-height:calc(100dvh - 64px);overflow:hidden;background:#fff; }
.prism-dialog > header, .prism-side-panel > header { display: flex; align-items: center; justify-content: space-between; padding: 20px; gap: 12px; min-height: 65px; border-bottom: 1px solid var(--prism-control-border); }
.prism-dialog > header {position:relative;padding:20px 50px 20px 20px;flex-shrink:0;}
.prism-dialog > header h2, .prism-side-panel > header h2 { font-size: 18px; font-weight: 600;line-height:1.4;color:#1f1f1f;margin:0;white-space:pre-line; }
.prism-dialog-close {position:absolute;top:20px;right:20px;display:inline-flex;border:0;padding:0;background:none;color:var(--foreground);cursor:pointer;}
.prism-dialog-body { padding: 24px;min-height:124px;max-height:663px;overflow-y:auto;display:grid;gap:20px; }
.prism-dialog > footer { padding: 20px; border-top: 1px solid var(--prism-control-border); display: flex; justify-content: flex-end; gap: 8px; }
.prism-dialog > footer {flex-shrink:0;background:var(--prism-base);}
.prism-confirm-dialog>header {height:65px;min-height:65px;padding:20px;}
.prism-confirm-dialog>header h2 {display:flex;align-items:center;gap:6px;line-height:25px;}
.prism-confirm-dialog .prism-dialog-body {min-height:0;}
.prism-confirm-dialog .prism-dialog-body>div {font-size:16px;font-weight:400;line-height:1.6;color:var(--foreground);white-space:pre-line;}
.prism-confirm-dialog>footer .prism-button {min-width:69px;}
.prism-confirm-dialog[data-no-title]>header,.prism-confirm-dialog[data-no-title]>footer {border:0;}
.prism-confirm-dialog[data-no-title] .prism-dialog-body {padding-top:0;}
.prism-side-panel { width: min(440px,100vw); padding: 0; border-left: 1px solid #dde5eb; }
.prism-side-panel > header { min-height: 64px; }
.prism-side-panel-body { padding: 20px; display: grid; gap: 20px; overflow-y: auto; }
.prism-sidebar { width: 280px; flex-shrink: 0; display: flex; flex-direction: column; background: var(--prism-lnb); border-right: 1px solid #dde5eb; overflow: hidden; }
.prism-sidebar[data-collapsed="true"] { width: 72px; }
.prism-sidebar > header { display: flex; align-items: center; justify-content: space-between; height: 64px; padding: 12px 24px; }
.prism-wordmark { font-size: 24px; font-weight: 750; color: var(--accent); padding: 0; border: 0; background: none; }
.prism-sidebar[data-collapsed="true"] > header { padding:12px 24px;height:64px; }
.prism-sidebar-new { padding: 0 24px; margin-bottom: 16px; }
.prism-sidebar[data-collapsed="true"] .prism-sidebar-new { padding: 0 16px; }
.prism-sidebar nav { padding: 0 12px; }
.prism-nav-item { display: flex; width: 100%; align-items: center; gap: 12px; border: 0; padding: 10px 12px; border-radius: 8px; background: transparent; font-size: 14px; text-align: left; min-height: 40px; }
.prism-nav-item svg { width: 24px; height: 24px; }
.prism-nav-item:hover, .prism-nav-item[aria-current] { background: var(--prism-panel); color: var(--accent); }
.prism-nav-child { padding-left: 48px; }
.prism-history { flex: 1; overflow-y: auto; margin-top: 16px; }
.prism-history h3 { font-size: 14px; font-weight: 600; padding: 8px 12px; }
.prism-history button { display: block; width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; text-align: left; background: none; border: 0; padding: 10px 12px; font-size: 14px; }
.prism-history button[aria-current] { background: var(--prism-panel); border-radius: 8px; }
.prism-sidebar > footer { padding: 20px 24px; margin-top: auto; border-top: 1px solid var(--prism-divider); }
.prism-sidebar[data-collapsed="true"] > footer { padding: 12px; }
.prism-chat-input { border: 1px solid #dde5eb; border-radius: 12px; background: #fff; box-shadow: var(--shadow-medium); overflow: hidden; }
.prism-chat-input:focus-within { outline: 2px solid var(--accent); outline-offset: 0; box-shadow: 2px 4px 20px #276acf1a; }
.prism-chat-input textarea { display: block; width: 100%; min-height: 60px; padding: 16px 16px 0; resize: vertical; border: 0; background: transparent; outline: none; font-size: 14px; font-weight: 500; line-height: 1.4; }
.prism-chat-input textarea:focus-visible { outline: none; }
.prism-chat-input textarea::placeholder { color: var(--prism-caption); }
.prism-chat-actions { height: 48px; padding: 10px 16px; display: flex; align-items: center; justify-content: space-between; }
.prism-chat-actions > span { color: var(--prism-caption); font-size: 10px; font-weight: 500; }
.prism-chat-actions > span.prism-error { color: var(--danger); }
.prism-chat-attachments { padding: 12px 16px 0; display: flex; gap: 4px; overflow-x: auto; }
.prism-message { margin: 20px 0; font-size: 16px; line-height: 1.6; overflow-wrap: anywhere; }
.prism-message[data-role="user"] { display: flex; flex-direction: column; align-items: flex-end; }
.prism-message[data-role="user"] .prism-message-content { max-width: 540px; min-width: 45px; padding: 8px 16px; border-radius: 20px 0 20px 20px; background: var(--prism-cool-100); font-size: 14px; font-weight: 500; white-space: pre-wrap; }
.prism-answer-status { margin: 10px 0; font-size: 12px; color: var(--muted); }
.prism-criteria { margin-top: 20px; padding-top: 20px; border-top: 1px solid #e9eaea; }
.prism-criteria ul { padding-left: 24px; border-left: 3px solid #e6ecf2; list-style: disc; }
.prism-criteria li { font-size: 16px; font-weight: 500; line-height: 1.6; }
.prism-candidate-card { padding: 16px; border: 1px solid var(--prism-control-border); border-radius: 12px; background: var(--prism-neutral-50); display: grid; gap: 12px; min-width: 0; }
.prism-candidate-card:hover { box-shadow: var(--shadow-float); }
.prism-candidate-card[data-selected] { border: 2px solid #0072c6; padding: 15px; }
.prism-rank { justify-self: start; padding: 6px 12px; height: 32px; border-radius: 8px; background: var(--surface); font-size: 14px; font-weight: 700; }
.prism-candidate-header { display: flex; gap: 12px; }
.prism-candidate-photo { flex-shrink: 0; width: 70px; height: 70px; border-radius: 8px; background: var(--prism-neutral-100); display: grid; place-items: center; font-size: 24px; color: var(--muted); overflow: hidden; }
.prism-candidate-photo img { width: 100%; height: 100%; object-fit: cover; object-position: top; }
.prism-candidate-info { flex: 1; min-width: 0; }
.prism-candidate-name { display: flex; align-items: center; gap: 4px; }
.prism-candidate-name button, .prism-candidate-cell button { padding: 0; border: 0; background: none; color: inherit; font-size: 16px; font-weight: 700; text-align: left; }
.prism-candidate-info p { margin: 2px 0; font-size: 14px; line-height: 1.4; }
.prism-candidate-info small { font-size: 12px; color: var(--prism-sub); }
.prism-candidate-card > .prism-chip { justify-self: start; }
.prism-candidate-summary { margin: 0; font-size: 14px; line-height: 1.6; }
.prism-candidate-cell { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; }
.prism-candidate-cell button { font-size: 14px; color: var(--accent); }
.prism-detail-list { margin: 0; }
