.prism-group-name .prism-error,.prism-user-current .prism-error {display:flex;align-items:center;gap:4px;font-size:12px;line-height:1.4;}
.prism-company-select-area,.prism-user-group-field {display:flex;flex-direction:column;gap:12px;min-width:0;}
.prism-domain-role-notice {padding:24px 12px;border-radius:8px;background:var(--prism-lnb);font-size:13px;line-height:1.4;text-align:center;color:var(--prism-sub);}
.prism-domain-company-box .prism-tag {color:#222;max-width:100%;min-width:0;min-height:21px;height:auto;overflow-wrap:anywhere;}
.prism-domain-company-box .prism-tag>button {flex-shrink:0;}
.prism-user-group-option {display:flex;align-items:center;gap:8px;min-width:0;width:100%;height:100%;}
.prism-user-group-option>.prism-chip {flex-shrink:0;}
.prism-user-group-option>span:last-child {min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.prism-company-current .prism-domain-form-actions,.prism-user-current .prism-domain-form-actions {flex-wrap:wrap;}
.prism-company-current .prism-domain-form-actions>div,.prism-user-current .prism-domain-form-actions>div {flex-wrap:wrap;}
@container (max-width:480px) {.prism-company-current .prism-domain-form-grid,.prism-user-current .prism-domain-form-grid {grid-template-columns:minmax(0,1fr);}}
.prism-chat-intro {position:relative;display:flex;flex-direction:column;justify-content:center;gap:40px;width:100%;max-width:800px;margin:0 auto;}
.prism-chat-intro>header {text-align:center;}
