.prism-intro-cards {display:flex;gap:10px;}
.prism-intro-cards>button {display:flex;flex-direction:column;flex:1;gap:14px;min-width:240px;padding:20px;border:1px solid var(--prism-cool-200);border-radius:12px;background:#fff;text-align:left;}
