.prism-print-page[data-repeat-header] {display:block;}
.prism-print-page h3 {font-size:10pt;font-weight:600;line-height:14pt;margin:0 0 8pt;}
.prism-print-summary>div {display:flex;gap:12pt;align-items:flex-start;}
.prism-print-summary p {font-size:10pt;line-height:14pt;margin:0;white-space:pre-line;}
