.prism-print-leader-badge {display:flex;align-items:center;justify-content:center;flex-shrink:0;width:55pt;height:55pt;border-radius:50%;background:var(--prism-cool-100);color:var(--prism-primary);font-size:10pt;font-weight:600;text-align:center;}
.prism-print-career ol {padding:0;margin:0;list-style:none;}
.prism-print-career li {display:flex;gap:8pt;align-items:baseline;padding:6pt 0;font-size:10pt;line-height:14pt;break-inside:avoid;}
.prism-print-career li>span:first-child {width:70pt;flex-shrink:0;}
.prism-print-career li>i {width:2pt;height:2pt;background:#868686;border-radius:50%;align-self:center;}
.prism-print-risk table {width:100%;border-collapse:collapse;font-size:9pt;line-height:13pt;}
.prism-print-risk th,.prism-print-risk td {padding:5pt;border:1px solid var(--prism-neutral-200);}
