.prism-print-risk td {text-align:center;}
.prism-print-experience {display:flex;flex-direction:column;gap:8pt;}
.prism-print-topics {display:flex;flex-wrap:wrap;gap:4pt;}
.prism-print-topics>span {padding:3pt 6pt;border-radius:20pt;border:1px solid var(--prism-control-border);font-size:9pt;}
.prism-print-topics>span[data-active] {background:var(--prism-primary);color:#fff;border-color:var(--prism-primary);}
.prism-print-page .prism-outline {padding:8pt;border-radius:6pt;break-inside:avoid;}
.prism-print-page .prism-outline p {font-size:10pt;line-height:14pt;white-space:pre-line;}
@media print {.prism-print-page {min-height:0;break-after:page;}.prism-print-page:last-child {break-after:auto;}.prism-print-repeat thead {display:table-header-group;}.prism-print-repeat td {border:0;}.prism-print-page button {display:none;}}

.prism-domain-profile-section {display:flex;flex-direction:column;gap:20px;padding-bottom:36px;}
.prism-domain-profile-section h3 {font-size:14px;font-weight:600;line-height:1.4;margin:0 0 10px;}
