.prism-sidebar[data-collapsed="true"] .prism-wordmark {display:none;}

.prism-multi-summary {position:absolute;left:12px;right:36px;top:50%;transform:translateY(-50%);display:flex;align-items:center;gap:4px;pointer-events:none;overflow:hidden;}
.prism-multi-chip {padding:2px 4px;gap:2px;min-width:0;}
