.prism-choice {position:relative;gap:8px;}
.prism-choice[data-size="small"] {gap:4px;}
.prism-choice[data-disabled] {color:#9DA3B3;}
.prism-checkbox {opacity:0!important;}
.prism-check-art {position:absolute;left:0;top:50%;transform:translateY(-50%);pointer-events:none;width:20px;height:20px;color:var(--prism-control-focus,#416395);}
