.prism-check-art>span {display:none;}
.prism-checkbox[data-state="unchecked"]~.prism-check-art>[data-glyph="unchecked"],.prism-checkbox[data-state="checked"]~.prism-check-art>[data-glyph="checked"],.prism-checkbox[data-state="indeterminate"]~.prism-check-art>[data-glyph="indeterminate"] {display:block;}
.prism-checkbox:focus-visible~.prism-check-art {outline:2px solid var(--focus);outline-offset:2px;border-radius:4px;}
.prism-radio-group .prism-choice>input[type="radio"] {position:absolute;left:0;top:50%;transform:translateY(-50%);opacity:0;width:20px;height:20px;margin:0;}
.prism-radio-group .prism-choice[data-size="small"]>input[type="radio"] {width:16px;height:16px;}
.prism-radio-group input[type="radio"]:focus-visible+.prism-icon {outline:2px solid var(--focus);outline-offset:2px;border-radius:50%;}

.prism-chip-autocomplete {position:relative;}
.prism-chip-autocomplete-control {display:flex;align-items:center;gap:4px;min-height:32px;padding:4px 12px;border:1px solid var(--prism-control-border);border-radius:6px;font-size:14px;font-weight:500;}
