.prism-chip-autocomplete-control>input {border:0;padding:0;outline:none;min-width:0;flex:1;height:22px;background:transparent;font-size:14px;}
.prism-chip-autocomplete-control>button {display:inline-flex;border:0;background:none;padding:0;flex-shrink:0;}
.prism-chip-autocomplete-options {position:absolute;top:100%;left:0;right:0;z-index:20;max-height:282px;overflow:auto;margin-top:4px;padding:6px 8px;border:1px solid var(--prism-control-border);border-radius:6px;background:var(--prism-base);}
.prism-chip-autocomplete-options>[role="option"] {display:flex;align-items:center;min-height:33px;padding:0 8px;border-radius:4px;font-size:14px;font-weight:500;cursor:pointer;white-space:pre;}
.prism-chip-autocomplete-options>[role="option"]:hover,.prism-chip-autocomplete-options>[aria-selected="true"] {background:var(--prism-neutral-100);}
.prism-chip-autocomplete-options mark {background:none;color:var(--prism-primary);}
.prism-chip-autocomplete-options>[aria-disabled="true"] {color:var(--prism-caption);cursor:not-allowed;}

.prism-autocomplete {position:relative;}
.prism-autocomplete-control {display:flex;align-items:center;gap:6px;height:32px;padding:6px 12px;border:1px solid var(--prism-control-border);border-radius:6px;background:var(--prism-base);}
.prism-autocomplete-control>input {min-width:0;width:100%;flex:1;border:0;padding:0;background:transparent;outline:none;font-size:14px;font-weight:500;}
