.prism-autocomplete-options {position:absolute;top:100%;left:0;right:0;z-index:30;display:flex;flex-direction:column;gap:2px;max-height:282px;overflow:auto;margin-top:4px;padding:6px 8px;border:1px solid var(--prism-control-border);border-radius:6px;background:var(--prism-base);}
.prism-autocomplete-options>[role="option"] {display:flex;align-items:center;min-height:33px;padding:0 8px;border-radius:4px;font-size:14px;font-weight:500;cursor:pointer;}
.prism-autocomplete-options>[role="option"]:hover,.prism-autocomplete-options>[data-active] {background:var(--prism-neutral-100);}
.prism-autocomplete-options>[aria-selected="true"] {color:var(--prism-blue-400);}
.prism-autocomplete-options>[aria-disabled="true"] {color:var(--prism-caption);cursor:not-allowed;}
.prism-autocomplete-options>p {min-height:33px;display:flex;align-items:center;justify-content:center;color:var(--prism-caption);font-size:14px;}

.prism-sidebar>header {flex-shrink:0;}
