.prism-history .prism-history-more {display:inline-flex;justify-content:center;align-items:center;width:16px;height:16px;flex-shrink:0;padding:0;border:0;border-radius:3px;opacity:0;color:#626a75;}
.prism-history-row:hover .prism-history-more,.prism-history-row:focus-within .prism-history-more,.prism-history-row[data-menu-open] .prism-history-more {opacity:1;}
