.prism-date-input[data-size="small"] {padding:5px 8px;border-radius:4px;}
.prism-date-input[data-size="small"] input {font-size:13px;}
.prism-date-input button {width:20px;height:20px;}
.prism-date-input svg {width:20px;height:20px;}
.prism-date-input[data-size="small"] button,.prism-date-input[data-size="small"] svg {width:16px;height:16px;}
.prism-date-input:not([data-disabled]):focus-within {border-color:#0072c6;}
.prism-date-input:not([data-disabled]):hover {border-color:var(--prism-blue-300);}
.prism-date-input[data-invalid] {border-color:var(--danger);}
.prism-calendar-popover {width:322px;max-width:calc(100vw - 32px);padding:12px 0;border:1px solid var(--prism-border);border-radius:6px;background:var(--prism-base);box-shadow:0 4px 10px #00000026;}
.prism-calendar-header {position:relative;height:40px;display:flex;align-items:center;justify-content:space-between;padding:0 12px;}
.prism-calendar-header>button {display:inline-flex;align-items:center;justify-content:center;border:0;padding:0 8px;background:none;cursor:pointer;color:var(--foreground);}
.prism-calendar-header>button:disabled {opacity:.4;cursor:default;}
.prism-calendar-header>.prism-calendar-year-toggle {position:absolute;left:50%;transform:translateX(-50%);gap:10px;font-size:16px;font-weight:600;line-height:1.6;color:#000;white-space:nowrap;}
.prism-calendar {width:320px;max-width:100%;padding:0 12px;border:0;border-radius:0;background:none;}
.prism-calendar .rdp-month,.prism-calendar .rdp-months {width:100%;}
.prism-calendar .rdp-month>* {margin:0;}
.prism-calendar .rdp-month_grid {width:100%;}
.prism-calendar .rdp-weekdays {height:40px;display:flex;align-items:center;justify-content:space-between;}
.prism-calendar .rdp-weekday {width:36px;font-size:13px;font-weight:500;color:var(--foreground);}
.prism-calendar .rdp-week {display:flex;justify-content:space-between;margin:2px 0;}
.prism-calendar .rdp-day {width:36px;height:36px;}
.prism-calendar .rdp-day_button {display:inline-flex;justify-content:center;align-items:center;width:36px;height:36px;padding:0;border:0;border-radius:50%;background:none;color:var(--foreground);font-size:14px;font-weight:400;line-height:1.4;}
.prism-calendar .rdp-day_button:hover {background:var(--prism-neutral-100);}
.prism-calendar .rdp-today .rdp-day_button {color:#0072c6;font-weight:700;}
.prism-calendar .rdp-outside .rdp-day_button,.prism-calendar .rdp-disabled .rdp-day_button {color:rgb(34 34 34 / 30%);opacity:1;}
.prism-calendar .rdp-selected .rdp-day_button {background:#0072c6;color:#fff;font-weight:400;}
.prism-calendar-years {display:grid;grid-template-columns:repeat(3,1fr);gap:4px;max-height:280px;overflow:auto;padding:8px 12px;}
.prism-calendar-years>button {height:36px;border:0;border-radius:18px;background:none;color:var(--foreground);font-size:16px;font-weight:400;cursor:pointer;}
.prism-calendar-years>button:hover {background:var(--prism-neutral-100);}
.prism-calendar-years>button[aria-checked="true"] {color:#fff;background:#0072c6;}

/* Radix tracks the anchor; the clipped rectangle preserves PRISM's arrow shape. */
.prism-tooltip[data-small]:not([data-panel]) {min-width:52px;padding:8px 12px;}
.prism-tooltip-arrow {width:12px;height:8.52px;overflow:hidden;pointer-events:none;}
.prism-tooltip-arrow::before {content:"";display:block;width:100%;height:100%;background:#0c1f4d;transform:rotate(45deg);}
.prism-tooltip[data-panel] .prism-tooltip-arrow::before {background:#fff;border:1px solid #dee7fb;border-radius:2px;}
.prism-tooltip[data-side="top"] > span:has(> .prism-tooltip-arrow) {transform:translateY(100%) !important;}
.prism-tooltip[data-side="bottom"] > span:has(> .prism-tooltip-arrow) {transform:translateY(-100%) !important;}
.prism-tooltip[data-side="left"] > span:has(> .prism-tooltip-arrow) {transform:translateX(100%) !important;}
.prism-tooltip[data-side="right"] > span:has(> .prism-tooltip-arrow) {transform:translateX(-100%) !important;}
.prism-tooltip[data-side="top"] .prism-tooltip-arrow::before {transform-origin:100% 0;}
.prism-tooltip[data-side="bottom"] .prism-tooltip-arrow::before {transform-origin:0 100%;}
.prism-tooltip[data-side="left"] .prism-tooltip-arrow,.prism-tooltip[data-side="right"] .prism-tooltip-arrow {width:8.52px;height:12px;}
.prism-tooltip[data-side="left"] .prism-tooltip-arrow::before {transform-origin:0 0;}
.prism-tooltip[data-side="right"] .prism-tooltip-arrow::before {transform-origin:100% 100%;}
.prism-tooltip:is([data-side="top"],[data-side="bottom"])[data-align="start"] > span:has(> .prism-tooltip-arrow) {left:16px !important;right:auto !important;}
.prism-tooltip:is([data-side="top"],[data-side="bottom"])[data-align="end"] > span:has(> .prism-tooltip-arrow) {left:auto !important;right:16px !important;}
.prism-pagination button[aria-label] {width:20px;min-width:20px;height:20px;padding:0;color:#424852;}
.prism-pagination button[aria-label]:disabled {color:#8a939f;}
.prism-pagination button[aria-label]:hover:not(:disabled) {background:transparent;color:#1f2228;}
.prism-pagination-pages {display:flex;align-items:center;gap:4px;min-width:0;max-width:100%;flex-wrap:wrap;justify-content:center;}
.prism-pagination {gap:6px;flex-wrap:wrap;}

.prism-candidate-list {display:flex;flex-direction:column;min-width:0;min-height:0;box-sizing:border-box;padding-top:36px;overflow:auto;container-type:inline-size;}
[data-prism="light"] .prism-candidate-list>.prism-candidate-filters {margin-bottom:0;flex-shrink:0;}
.prism-candidate-list .prism-candidate-filters>div:first-child>.prism-field:last-child>label,
.prism-candidate-page-size .prism-field>label {position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap;}
.prism-candidate-toolbar {display:flex;flex:none;align-items:center;justify-content:space-between;gap:20px;margin-top:24px;margin-bottom:10px;min-width:0;}
.prism-candidate-toolbar-info {display:flex;align-items:center;gap:10px;min-width:0;}
.prism-candidate-toolbar-actions {display:flex;align-items:center;gap:8px;}
.prism-candidate-summary {display:flex;align-items:center;gap:6px;font-size:14px;font-weight:500;line-height:1.4;}
.prism-candidate-summary>span {white-space:nowrap;color:#363636;}
.prism-candidate-summary>span:last-child {color:#868686;}
.prism-candidate-page-size {width:120px;flex:none;}
.prism-candidate-page-size .prism-field {gap:0;}
.prism-candidate-directory {flex:1;min-width:0;min-height:120px;overflow:auto;border-bottom:1px solid var(--prism-neutral-200);}
.prism-candidate-directory table {width:max(100%,640px);border-collapse:separate;border-spacing:0;table-layout:fixed;}
.prism-candidate-directory th,.prism-candidate-directory td {font-family:inherit;font-size:14px;line-height:1.4;border-bottom:1px solid var(--prism-neutral-200);border-right:1px solid var(--prism-neutral-200);}
.prism-candidate-directory th {position:sticky;top:0;z-index:1;text-align:left;padding:6px 10px;font-weight:600;background:var(--prism-cool-100);color:var(--foreground);}
.prism-candidate-directory td {padding:10px;font-weight:400;background:var(--prism-base);}
.prism-candidate-directory th:last-child,.prism-candidate-directory td:last-child {border-right:0;}
.prism-candidate-directory tbody tr:last-child>td {border-bottom:0;}
.prism-candidate-directory th:nth-child(2) {width:20%;}
.prism-candidate-directory th:nth-child(3) {width:15%;}
.prism-candidate-directory th:nth-child(4) {width:20%;}
.prism-candidate-directory .prism-candidate-check {width:48px;padding:0;text-align:center;}
.prism-candidate-sort {display:flex;align-items:center;justify-content:space-between;gap:4px;width:100%;}
.prism-candidate-sort>button {display:inline-flex;border:0;padding:0;background:none;color:var(--prism-neutral-400);cursor:pointer;}
.prism-candidate-sort>button:disabled {cursor:default;opacity:.5;}
.prism-candidate-directory .prism-profile-chip {max-width:100%;white-space:nowrap;}
.prism-candidate-directory .prism-profile-chip-image {flex:none;}
.prism-candidate-directory-text {overflow:hidden;white-space:nowrap;text-overflow:ellipsis;}
.prism-candidate-directory .prism-favorite-toggle {width:20px;height:20px;padding:0;}
.prism-candidate-directory .prism-favorite-toggle svg {width:20px;height:20px;}
.prism-candidate-directory .prism-candidate-empty {border:0;padding:0;height:400px;}
.prism-candidate-directory:has(.prism-candidate-empty) {border-bottom:0;}
.prism-candidate-pagination {display:flex;flex:none;justify-content:center;padding:20px 0;}
.prism-candidate-feedback {flex:none;max-width:100%;margin-bottom:10px;}
.prism-candidate-feedback .prism-button {color:white;}
.prism-candidate-confirm-note {display:block;margin-top:8px;font-size:14px;line-height:1.4;color:#868686;}
@container (max-width:600px) {
    [data-prism="light"] .prism-candidate-list>.prism-candidate-filters {flex-wrap:wrap;gap:12px;}
    [data-prism="light"] .prism-candidate-list>.prism-candidate-filters>div:first-child {flex-basis:100%;}
    .prism-candidate-toolbar {flex-wrap:wrap;gap:10px;}
    .prism-candidate-toolbar-info {flex-wrap:wrap;gap:8px;}
}
@container (max-width:360px) {
    [data-prism="light"] .prism-candidate-list>.prism-candidate-filters>div:first-child {grid-template-columns:minmax(0,1fr);}
    .prism-candidate-summary {flex-wrap:wrap;}
    .prism-candidate-toolbar-actions {flex-wrap:wrap;}
    .prism-candidate-list {padding-top:16px;}
}

/* Responsive/sizing extensions retain the desktop PRISM baseline. */
.prism-panel-placeholder[data-open] {width:min(var(--prism-panel-width,440px),100%);}
.prism-panel {width:min(var(--prism-panel-width,440px),100%);overflow:visible;}
.prism-panel[data-expanded],.prism-panel[data-compact] {width:100%;}
.prism-panel-placeholder[data-compact] {width:0;}
.prism-panel-content {container-type:inline-size;container-name:prism-content;}
.prism-panel-resizer {position:absolute;left:-4px;top:0;bottom:0;z-index:2;width:8px;cursor:col-resize;touch-action:none;user-select:none;background:transparent;}
.prism-panel-resizer::after {content:"";position:absolute;top:calc(50% - 18px);left:3px;width:2px;height:36px;border-radius:2px;background:var(--prism-control-border);}
.prism-panel-resizer:hover::after,.prism-panel-resizer:focus-visible::after {background:var(--prism-blue-300);}
.prism-workspace {container-type:inline-size;container-name:prism-shell;}
.prism-workspace-header>strong {min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.prism-workspace[data-compact] .prism-workspace-header {padding:12px;height:auto;min-height:64px;flex-wrap:wrap;}
.prism-workspace[data-compact] .prism-workspace-header>.prism-help {font-size:11px;}
.prism-mobile-navigation {display:flex;flex-direction:column;width:280px;max-width:calc(100vw - 16px);padding:0;overflow:hidden;}
.prism-mobile-navigation>header {height:52px;flex:none;display:flex;align-items:center;justify-content:space-between;padding:8px 12px;border-bottom:1px solid var(--prism-border);}
.prism-mobile-navigation>header h2 {font-size:16px;}
.prism-mobile-navigation>div {flex:1;min-height:0;}
.prism-mobile-navigation .prism-sidebar {width:100%;height:100%;}
.prism-pdf {container-type:inline-size;container-name:prism-pdf;}
.prism-pdf-viewport {display:block;}
.prism-pdf-viewport canvas {display:block;margin-inline:auto;}
@container prism-pdf (max-width:520px) {.prism-pdf-toolbar {display:flex;flex-wrap:wrap;justify-content:space-between;padding:10px;gap:8px;}.prism-pdf-toolbar>:last-child {margin-left:auto;}}
@container prism-shell (max-width:640px) {.prism-workspace-messages,.prism-workspace-list {padding:16px;}.prism-workspace-composer {padding:12px;}.prism-chat-welcome {margin:30px auto;}}
@container prism-content (max-width:520px) {.prism-summary-badge {flex-direction:column;align-items:center;}.prism-summary-badge>div:last-child {border-left:0;border-top:1px solid var(--prism-border);width:100%;}.prism-favorite-photo {width:88px;min-width:88px;height:88px;}.prism-date-fields {flex-wrap:wrap;}.prism-date-fields>.prism-field {flex-basis:100%;}}
@media (max-width:480px) {.prism-dialog {max-width:calc(100vw - 24px);max-height:calc(100dvh - 24px);}.prism-dialog-body {padding:16px;}.prism-dialog>header,.prism-dialog>footer {padding:16px;}.prism-calendar-popover {max-width:calc(100vw - 24px);}.prism-calendar {width:min(320px,calc(100vw - 26px));}.prism-calendar .rdp-month,.prism-calendar .rdp-month_grid {width:100%;}.prism-admin-header,.prism-admin-toolbar {flex-wrap:wrap;}.prism-admin-body {padding:16px;}}
.prism-candidate-card {position:relative;container-type:inline-size;word-break:break-word;}
.prism-candidate-header>.prism-favorite-toggle {position:absolute;right:0;top:0;z-index:2;}
.prism-candidate-name {padding-right:24px;min-width:0;}
.prism-candidate-label {min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:16px;font-weight:700;line-height:1.6;}
.prism-candidate-open {position:absolute;inset:0;padding:0;border:0;background:transparent;cursor:pointer;z-index:1;border-radius:12px;}
.prism-candidate-open:focus-visible {outline:2px solid var(--prism-blue-300);outline-offset:2px;}
.prism-candidate-extra {position:relative;z-index:2;}
.prism-candidate-card button:not(.prism-candidate-open),.prism-candidate-card a {position:relative;z-index:2;}
.prism-candidate-header>.prism-favorite-toggle {position:absolute;}
.prism-candidate-categories {display:flex;flex-wrap:wrap;gap:0;font-size:12px;font-weight:500;line-height:1.4;color:#363636;}
.prism-candidate-categories>b:not(:last-child)::after {content:"";display:inline-block;width:1px;height:10px;background:var(--prism-control-border);margin:0 6px;}
.prism-candidate-brief {display:flex;flex-direction:column;gap:10px;background:#fff;padding:12px;border-radius:8px;}
.prism-candidate-brief>div {display:flex;align-items:flex-start;gap:2px;}
.prism-candidate-brief dt {flex:0 0 80px;color:var(--foreground);font-size:12px;font-weight:600;line-height:1.4;}
.prism-candidate-brief dd {flex:1;min-width:0;color:#363636;font-size:12px;font-weight:400;line-height:1.4;}
.prism-candidate-brief dt>small {display:block;font-size:10px;font-weight:400;color:var(--prism-sub);}
.prism-candidate-brief>hr {width:100%;margin:0;border:0;border-top:1px solid var(--prism-border);}
.prism-candidate-detail-button {display:flex;align-items:center;justify-content:center;gap:4px;line-height:1.4;}
.prism-candidate-card[data-panel] .prism-candidate-header {min-height:104px;flex-direction:row;}
@container (max-width:260px) {.prism-candidate-brief>div {flex-direction:column;}.prism-candidate-brief dt {flex:none;}}
.prism-compensation,.prism-compensation-grid,.prism-leadership-trend,.prism-domain-profile-section,.prism-outline {min-width:0;max-width:100%;}
.prism-domain-profile-section {grid-template-columns:minmax(0,1fr);}
.prism-domain-profile-section>* {min-width:0;}
